import React, { useState, useEffect } from "react";
import {
  Rating,
  CircularProgress,
  Box,
  Typography,
  Card,
  CardContent,
  Avatar,
  Dialog,
  IconButton,
  Chip,
  Button,
} from "@mui/material";
import Masonry from "@mui/lab/Masonry";
import UserAvatar from "../Components/UserAvatar";
import { Close, NavigateBefore, NavigateNext } from "@mui/icons-material";

const Testimonial = () => {
  const [testimonials, setTestimonials] = useState([]);
  const [displayTestimonials, setDisplayTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageDialogOpen, setImageDialogOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [selectedTestimonial, setSelectedTestimonial] = useState(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [showAll, setShowAll] = useState(false);
  const itemsPerPage = 15;

  const GOOGLE_SCRIPT_URL =
    "https://script.google.com/macros/s/AKfycbxu79sYZb_yIEeM9pLZczPCAtw6AGCM0JpWYu2GuNWqyzTFh7FvwkmVG1SueS9JwC5lBA/exec";

  // Fixed function to convert Google Drive URLs to direct image URLs
  const getGoogleDriveImageUrl = (url) => {
    if (!url) {
      console.log("No URL provided");
      return null;
    }

    console.log("Processing URL:", url);

    if (url.includes("drive.google.com/file/d/")) {
      const fileId = url.match(/\/file\/d\/([^\/]+)/)?.[1];
      console.log("Extracted fileId:", fileId);

      if (fileId) {
        const urlsToTry = [
          `https://drive.google.com/thumbnail?id=${fileId}&sz=w200`, // Thumbnail
          `https://lh3.googleusercontent.com/d/${fileId}=s200`, // Google Docs viewer
          `https://drive.google.com/uc?export=view&id=${fileId}`, // Original direct
        ];

        console.log("URLs to try:", urlsToTry);
        return urlsToTry[0];
      }
    }

    console.log("Returning original URL (not a Google Drive URL)");
    return url;
  };

  // Function to parse additional photos
  const parseAdditionalPhotos = (photosData) => {
    console.log("Raw photos data:", photosData);

    if (
      !photosData ||
      photosData === "No additional photos" ||
      photosData === "Error storing photo"
    ) {
      return [];
    }

    try {
      let urlsArray = [];

      if (Array.isArray(photosData)) {
        urlsArray = photosData;
      } else if (typeof photosData === "string") {
        // Split by comma and clean up the URLs
        urlsArray = photosData
          .split(",")
          .map((url) => url.trim())
          .filter(
            (url) =>
              url &&
              url !== "Error storing photo" &&
              url !== "No additional photos"
          );
      } else {
        urlsArray = [photosData];
      }

      console.log("URLs array:", urlsArray);

      // Convert to direct Google Drive URLs using the new method
      const directUrls = urlsArray.map((url) => getGoogleDriveImageUrl(url));

      console.log("Direct URLs:", directUrls);
      return directUrls.filter((url) => url);
    } catch (error) {
      console.error("Error parsing additional photos:", error);
      return [];
    }
  };

  const fetchTestimonials = async () => {
    try {
      setLoading(true);
      setError(null);
      console.log("Fetching testimonials...");

      const response = await fetch(
        `${GOOGLE_SCRIPT_URL}?action=getTestimonials`
      );
      if (!response.ok)
        throw new Error(`Failed to fetch testimonials: ${response.status}`);

      const data = await response.json();
      console.log("Raw API response:", data);

      if (data.success && data.testimonials) {
        // Process testimonials
        const processedTestimonials = data.testimonials.map(
          (testimonial, index) => {
            const additionalPhotos = parseAdditionalPhotos(
              testimonial.additionalPhotos
            );
            const profilePhoto =
              testimonial.photo && testimonial.photo !== "No photo"
                ? getGoogleDriveImageUrl(testimonial.photo)
                : null;

            console.log(`Testimonial ${index}:`, {
              name: testimonial.name,
              profilePhoto: testimonial.photo,
              convertedProfilePhoto: profilePhoto,
              additionalPhotosRaw: testimonial.additionalPhotos,
              additionalPhotosConverted: additionalPhotos,
            });

            return {
              ...testimonial,
              additionalPhotos: additionalPhotos,
              photo: profilePhoto,
            };
          }
        );

        console.log("Final processed testimonials:", processedTestimonials);
        setTestimonials(processedTestimonials);
        setDisplayTestimonials(processedTestimonials.slice(0, itemsPerPage));
      } else {
        throw new Error(data.message || "No testimonials found");
      }
    } catch (err) {
      console.error("Fetch error:", err);
      setError(err.message);
      setTestimonials([]);
      setDisplayTestimonials([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTestimonials();
  }, []);

  useEffect(() => {
    if (showAll) {
      setDisplayTestimonials(testimonials);
    } else {
      setDisplayTestimonials(testimonials.slice(0, itemsPerPage));
    }
  }, [showAll, testimonials]);

const handleImageClick = (testimonial, imageUrl, index = 0) => {
  console.log("Image clicked:", { imageUrl, index, testimonial });
  setSelectedTestimonial(testimonial);
  setSelectedImage(imageUrl);
  setCurrentImageIndex(index); // Start from 0 for additional photos
  setImageDialogOpen(true);
};

  const handleCloseDialog = () => {
    setImageDialogOpen(false);
    setSelectedImage(null);
    setSelectedTestimonial(null);
    setCurrentImageIndex(0);
  };

  const handleNextImage = () => {
  if (selectedTestimonial) {
    const allImages = (selectedTestimonial.additionalPhotos || []).filter(img => img && img !== "No photo");
    if (allImages.length === 0) return;
    
    const nextIndex = (currentImageIndex + 1) % allImages.length;
    setCurrentImageIndex(nextIndex);
    setSelectedImage(allImages[nextIndex]);
  }
};

 const handlePrevImage = () => {
  if (selectedTestimonial) {
    const allImages = (selectedTestimonial.additionalPhotos || []).filter(img => img && img !== "No photo");
    if (allImages.length === 0) return;
    
    const prevIndex = (currentImageIndex - 1 + allImages.length) % allImages.length;
    setCurrentImageIndex(prevIndex);
    setSelectedImage(allImages[prevIndex]);
  }
};

  const toggleShowAll = () => {
    setShowAll(!showAll);
  };

  // Test function to check image URLs
  const testImageUrl = (url) => {
    if (!url) return false;

    // Check if it's a Google Drive URL that we can process
    const isProcessableUrl =
      url.includes("drive.google.com") || url.includes("googleusercontent.com");
    console.log(`Testing URL: ${url} - Is processable: ${isProcessableUrl}`);

    return isProcessableUrl;
  };

  if (loading) {
    return (
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          minHeight: 400,
          background:
            "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
          color: "white",
        }}
      >
        <Box sx={{ textAlign: "center" }}>
          <CircularProgress sx={{ color: "#FF9800", mb: 2 }} />
          <Typography variant="h6">Loading testimonials...</Typography>
        </Box>
      </Box>
    );
  }

  if (error) {
    return (
      <Box
        sx={{
          textAlign: "center",
          minHeight: 400,
          background:
            "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
          color: "white",
          padding: 4,
        }}
      >
        <Typography variant="h4" color="error" gutterBottom>
          Error Loading Testimonials
        </Typography>
        <Typography variant="body1">{error}</Typography>
        <Button
          onClick={fetchTestimonials}
          variant="contained"
          sx={{ background: "#FF9800", mt: 2 }}
        >
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box
      id="testimonials"
      sx={{
        background:
          "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white",
        p: { xs: 3, md: 6 },
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        textAlign: "center",
      }}
    >
      <Typography
        variant="h4"
        component="h4"
        sx={{
          mb: 5,
          fontFamily: "'AlanSans', sans-serif",
          fontWeight: 700,
          background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
          backgroundClip: "text",
          WebkitBackgroundClip: "text",
          color: "transparent",
        }}
      >
        What They've Said
      </Typography>

      <Box sx={{ width: "100%", maxWidth: 1200, justifyContent: "center" }}>
        <Masonry columns={{ xs: 1, sm: 2, md: 3 }} spacing={3}>
          {displayTestimonials.map((testimonial, index) => {
            const additionalPhotos = testimonial.additionalPhotos || [];
            const hasAdditionalPhotos = additionalPhotos.length > 0;

            return (
              <Card
                key={index}
                sx={{
                  background: "rgba(255,255,255,0.05)",
                  backdropFilter: "blur(10px)",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: 2,
                  overflow: "hidden",
                  transition: "transform 0.3s ease, box-shadow 0.3s ease",
                  "&:hover": {
                    transform: "translateY(-5px)",
                  },
                }}
              >
                <CardContent
                  sx={{
                    p: 2,
                    display: "flex",
                    flexDirection: "column",
                    textAlign: "left",
                  }}
                >
                  <Box sx={{ display: "flex", alignItems: "center", mb: 1 }}>
                    <UserAvatar
                      photoUrl={testimonial.photo}
                      name={testimonial.name}
                    />

                    <Box sx={{ ml: 2 }}>
                      <Typography
                        variant="subtitle1"
                        sx={{
                          color: "#FFFF",
                          fontWeight: 600,
                          fontFamily: "'AlanSans', sans-serif",
                        }}
                      >
                        {testimonial.name}
                      </Typography>
                      <Rating
                        value={testimonial.rating}
                        readOnly
                        size="small"
                        sx={{
                          color: "#FF9800",
                          "& .MuiRating-iconFilled": { color: "#FF9800" },
                        }}
                      />
                      <Typography
                        variant="caption"
                        sx={{
                          color: "rgba(255,255,255,0.5)",
                          display: "block",
                          mt: 0.5,
                        }}
                      >
                        {new Date(testimonial.timestamp).toLocaleDateString()}
                      </Typography>
                    </Box>
                  </Box>

                  <div className="relative text-[rgba(255,255,255,0.9)] font-in px-2 text-center flex  mb-2">
                    <p>
                      <b className=" px-2 text-[#ff9800] text-2xl font-riope">
                        "
                      </b>
                      {testimonial.comment}
                      <b className=" px-2 text-[#ff9800] text-2xl font-riope">
                        "
                      </b>
                    </p>
                  </div>

                  {/* Additional Photos Masonry */}
                  {hasAdditionalPhotos && (
                    <Box sx={{ mt: 2 }}>
                      {/* <Typography variant="caption" sx={{ color: "rgba(255,255,255,0.7)", mb: 1, display: "block" }}>
                        Additional Photos ({additionalPhotos.length}):
                      </Typography> */}
                      <Box
                        sx={{
                          display: "grid",
                          gridTemplateColumns: "repeat(3, 1fr)",
                          gap: 1,
                        }}
                      >
                        {additionalPhotos.map((photoUrl, photoIndex) => {
                          const isValidUrl = testImageUrl(photoUrl);

                          return (
                            <Box
                              key={photoIndex}
                              onClick={() =>
                                handleImageClick(
                                  testimonial,
                                  photoUrl,
                                  photoIndex + 1
                                )
                              }
                              sx={{
                                cursor: "pointer",
                                borderRadius: 1,
                                overflow: "hidden",
                                transition: "transform 0.2s ease",
                                "&:hover": {
                                  transform: "scale(1.05)",
                                },
                                aspectRatio: "1",
                                backgroundColor: isValidUrl
                                  ? "rgba(255,255,255,0.1)"
                                  : "rgba(255,0,0,0.3)",
                                border: isValidUrl
                                  ? "1px solid rgba(255,255,255,0.2)"
                                  : "1px solid rgba(255,0,0,0.5)",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                position: "relative",
                              }}
                            >
                              {isValidUrl ? (
                                <img
                                  src={photoUrl}
                                  alt={`Additional photo ${photoIndex + 1} by ${
                                    testimonial.name
                                  }`}
                                  style={{
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                    display: "block",
                                  }}
                                  onError={(e) => {
                                    console.error(
                                      "Image failed to load:",
                                      photoUrl
                                    );
                                    e.target.style.display = "none";
                                    // Show error indicator
                                    e.target.parentElement.innerHTML = `
                                      <div style="color: rgba(255,255,255,0.7); font-size: 10px; text-align: center; padding: 4px;">
                                        ❌ Load Failed<br/>
                                        <small>${photoUrl.substring(
                                          0,
                                          20
                                        )}...</small>
                                      </div>
                                    `;
                                  }}
                                  onLoad={() =>
                                    console.log(
                                      "Image loaded successfully:",
                                      photoUrl
                                    )
                                  }
                                />
                              ) : (
                                <div
                                  style={{
                                    color: "white",
                                    fontSize: "10px",
                                    textAlign: "center",
                                    padding: "4px",
                                  }}
                                >
                                  ⚠️ Invalid URL
                                  <br />
                                  <small>{photoUrl.substring(0, 20)}...</small>
                                </div>
                              )}
                            </Box>
                          );
                        })}
                      </Box>
                    </Box>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </Masonry>

        {/* View More/Less Button */}
        {testimonials.length > itemsPerPage && (
          <Box sx={{ display: "flex", justifyContent: "center", mt: 4 }}>
            <Button
              onClick={toggleShowAll}
              variant="outlined"
              sx={{
                color: "#FF9800",
                borderColor: "#FF9800",
                "&:hover": {
                  borderColor: "#FF5722",
                  backgroundColor: "rgba(255,152,0,0.1)",
                },
              }}
            >
              {showAll
                ? "View Less"
                : `View More (${testimonials.length - itemsPerPage} more)`}
            </Button>
          </Box>
        )}
      </Box>

      {/* Image Dialog */}
      <Dialog
        open={imageDialogOpen}
        onClose={handleCloseDialog}
        maxWidth="lg"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background: "rgba(0,0,0,0.9)",
            color: "white",
          },
        }}
      >
        {selectedImage && selectedTestimonial && (
          <>
            <IconButton
              onClick={handleCloseDialog}
              sx={{
                position: "absolute",
                right: 8,
                top: 8,
                color: "white",
                background: "rgba(0,0,0,0.5)",
                "&:hover": {
                  background: "rgba(255,0,0,0.5)",
                },
                zIndex: 1000,
              }}
            >
              <Close />
            </IconButton>

            <IconButton
              onClick={handlePrevImage}
              sx={{
                position: "absolute",
                left: 8,
                top: "50%",
                transform: "translateY(-50%)",
                color: "white",
                background: "rgba(0,0,0,0.5)",
                "&:hover": {
                  background: "rgba(255,152,0,0.5)",
                },
                zIndex: 1000,
              }}
            >
              <NavigateBefore />
            </IconButton>

            <IconButton
              onClick={handleNextImage}
              sx={{
                position: "absolute",
                right: 8,
                top: "50%",
                transform: "translateY(-50%)",
                color: "white",
                background: "rgba(0,0,0,0.5)",
                "&:hover": {
                  background: "rgba(255,152,0,0.5)",
                },
                zIndex: 1000,
              }}
            >
              <NavigateNext />
            </IconButton>

            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                p: 2,
                minHeight: "400px",
                backgroundColor: "rgba(255,255,255,0.1)",
              }}
            >
              <img
                src={selectedImage}
                alt="Enlarged view"
                style={{
                  maxWidth: "100%",
                  maxHeight: "70vh",
                  objectFit: "contain",
                }}
                onError={(e) => {
                  console.error("Dialog image failed to load:", selectedImage);
                  e.target.style.display = "none";
                  e.target.parentElement.innerHTML = `
                    <div style="color: white; text-align: center; padding: 20px;">
                      <div style="font-size: 24px; margin-bottom: 10px;">❌</div>
                      <div>Image failed to load</div>
                      <div style="font-size: 10px; opacity: 0.7; margin-top: 5px; word-break: break-all;">
                        ${selectedImage}
                      </div>
                      <div style="font-size: 12px; opacity: 0.7; margin-top: 10px;">
                        Check if the file is publicly shared on Google Drive
                      </div>
                    </div>
                  `;
                }}
                onLoad={() =>
                  console.log("Full image loaded successfully:", selectedImage)
                }
              />
            </Box>

            <Box sx={{ p: 2, borderTop: "1px solid rgba(255,255,255,0.1)" }}>
              <Box
                sx={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                }}
              >
                <Box>
                  <Typography
                    variant="h6"
                    sx={{
                      color: "white",
                      fontFamily: "'AlanSans', sans-serif",
                    }}
                  >
                    {selectedTestimonial.name}
                  </Typography>
                  <Rating
                    value={selectedTestimonial.rating}
                    readOnly
                    size="small"
                    sx={{ color: "#FF9800" }}
                  />
                </Box>
                <Chip
                  label={`${currentImageIndex} / ${
                    (selectedTestimonial.additionalPhotos || []).filter(
                      (img) => img && img !== "No photo"
                    ).length
                  }`}
                  sx={{ color: "white", background: "rgba(255,152,0,0.3)" }}
                />
              </Box>
              <Typography
                variant="body2"
                sx={{ color: "rgba(255,255,255,0.8)", mt: 1 }}
              >
                {selectedTestimonial.comment}
              </Typography>
            </Box>
          </>
        )}
      </Dialog>

      {testimonials.length === 0 && !loading && (
        <Box sx={{ textAlign: "center", mt: 4 }}>
          <Typography variant="h6" sx={{ color: "rgba(255,255,255,0.7)" }}>
            No testimonials yet. Be the first to share your experience!
          </Typography>
        </Box>
      )}
    </Box>
  );
};

export default Testimonial;
